impl Solution{pub fn permute_unique(mut a:Vec<i32>)->Vec<Vec<i32>>{a.sort_unstable();fn f(a:&[i32],u:&mut Vec<bool>,v:&mut Vec<i32>,o:&mut Vec<Vec<i32>>){if v.len()==a.len(){o.push(v.clone());return}for i in 0..a.len(){if u[i]||(i>0&&a[i]==a[i-1]&&!u[i-1]){continue}u[i]=true;v.push(a[i]);f(a,u,v,o);v.pop();u[i]=false;}}let mut o=vec![];f(&a,&mut vec![false;a.len()],&mut vec![],&mut o);o}}
